// Puxa o conversionReport da Shopee Affiliate API COM PAGINACAO (scrollId).
// Assina cada chamada: SHA256(AppId + Timestamp + Payload + Secret).
// Variaveis de ambiente do n8n: SHOPEE_APP_ID, SHOPEE_SECRET.
// NOTA DE SCHEMA: orderId fica em orders[].orderId (nao no node) e o valor da venda
// (GMV) vem de orders[].items[].actualAmount. campaignType NAO existe no node -> a
// campanha sai do utmContent (subId). Confirme os nomes com 1 resposta real antes de
// escalar; o mapeamento abaixo e defensivo (cai pra n.orderId se nao houver orders).
const APP_ID = $env.SHOPEE_APP_ID;
const SECRET = $env.SHOPEE_SECRET;
if (!APP_ID || !SECRET) throw new Error('Defina SHOPEE_APP_ID e SHOPEE_SECRET nas variaveis do n8n');
const ENDPOINT = 'https://open-api.affiliate.shopee.com.br/graphql';

async function call(query) {
  const payload = JSON.stringify({ query });
  const ts = Math.floor(Date.now() / 1000);
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`${APP_ID}${ts}${payload}${SECRET}`));
  const sig = [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
  const res = await fetch(ENDPOINT, { method: 'POST', headers: {
    'Content-Type': 'application/json',
    Authorization: `SHA256 Credential=${APP_ID}, Timestamp=${ts}, Signature=${sig}`
  }, body: payload });
  const j = await res.json();
  if (j.errors) throw new Error(JSON.stringify(j.errors));
  return j.data;
}

const fim = Math.floor(Date.now() / 1000);
const ini = fim - 7 * 24 * 3600; // janela de 7 dias (reprocessa; o ingest e idempotente). Max ~90d.

const out = [];
let scrollId = null, pages = 0;
do {
  const scroll = scrollId ? `, scrollId: "${scrollId}"` : '';
  const data = await call(`query { conversionReport(purchaseTimeStart: ${ini}, purchaseTimeEnd: ${fim}, limit: 500${scroll}) { nodes { conversionId purchaseTime utmContent totalCommission netCommission orders { orderId orderStatus items { actualAmount itemPrice qty } } } pageInfo { scrollId hasNextPage } } }`);
  const cr = (data && data.conversionReport) || {};
  for (const n of (cr.nodes || [])) {
    const orders = (n.orders && n.orders.length) ? n.orders : [{ orderId: n.orderId || n.conversionId, items: [] }];
    for (const o of orders) {
      const value = (o.items || []).reduce((s, it) => s + (Number(it.actualAmount) || (Number(it.itemPrice) || 0) * (Number(it.qty) || 1)), 0);
      out.push({ json: {
        conversion_id: `${n.conversionId}:${o.orderId || ''}`,
        order_id: o.orderId || null,
        order_status: o.orderStatus || null,
        click_id: n.utmContent,
        purchase_time: Number(n.purchaseTime) || null,
        value: value || null,
        total_commission: Number(n.totalCommission) || 0,
        net_commission: Number(n.netCommission) || 0
      } });
    }
  }
  scrollId = cr.pageInfo && cr.pageInfo.hasNextPage ? cr.pageInfo.scrollId : null;
  pages++;
} while (scrollId && pages < 50); // teto de seguranca: 50 paginas x 500 = 25k vendas/janela

return out;
